1	package review
2	
3	import (
4		"encoding/json"
5		"regexp"
6		"strings"
7	
8		reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
9	)
10	
11	// trailFindingsJSONInstructions is the trail-mode output contract. Reviewers
12	// and the judge end with this JSON line so posting reads their findings
13	// structurally instead of interpreting prose. The example line must parse
14	// with splitTrailJSON; a test enforces that.
15	const trailFindingsJSONInstructions = `Final line (required, read by a program):
16	End your output with exactly one line holding only this JSON object, with no code fence and nothing after it:
17	{"summary":"one-sentence verdict","comments":[{"severity":"high","body":"bug; impact; fix","location":{"granularity":"line","file_path":"path/to/file.go","start_line":42}}]}
18	- Add one comment per actionable finding reported above, with the same severity: high, medium, or low.
19	- location.granularity is line (with start_line), range (with start_line and end_line), file, or whole_change.
20	- If nothing is actionable, use an empty array: "comments":[].
21	- This line is required even where other instructions say to output nothing else.`
22	
23	// maxTrailJSONLines bounds the backward scan for a pretty-printed JSON block.
24	const maxTrailJSONLines = 200
25	
26	// TrailComment is one finding in the trail JSON contract.
27	type TrailComment struct {
28		Severity   string        `json:"severity"`
29		Confidence *float64      `json:"confidence,omitempty"`
30		Body       string        `json:"body"`
31		Location   TrailLocation `json:"location"`
32	}
33	
34	// TrailLocation anchors a TrailComment to the change.
35	type TrailLocation struct {
36		Granularity  string `json:"granularity"`
37		FilePath     string `json:"file_path,omitempty"`
38		StartLine    int    `json:"start_line,omitempty"`
39		EndLine      int    `json:"end_line,omitempty"`
40		SelectedText string `json:"selected_text,omitempty"`
41	}
42	
43	// TrailReport is what a trail-mode run posts: structured comments from
44	// reviews that honored the JSON contract, and the prose, with any contract
45	// line removed, of those that did not. At least one of the two is set.
46	type TrailReport struct {
47		Comments []TrailComment
48		Prose    string
49	}
50	
51	// trailReportFor decides what a trail-mode run posts. It returns post=false
52	// only when the JSON contract reports no findings and nothing in the prose
53	// contradicts that; every malformed or contradictory case posts, so a
54	// misbehaving model costs an extra finding rather than a lost one. A posted
55	// report is empty only when the output had nothing readable. When a judge
56	// ran, its verdict decides: it is asked to drop unsupported claims.
57	func trailReportFor(summary reviewtypes.RunSummary, aggregateOutput string) (TrailReport, bool) {
58		if verdict := strings.TrimSpace(aggregateOutput); verdict != "" {
59			prose, comments, ok := splitTrailJSON(verdict)
60			if !contractCoversProse(prose, comments, ok) {
61				if prose == "" {
62					// A JSON-only reply without a summary has no prose of its own.
63					prose = combinedReviewNarratives(usableAgentRuns(summary))
64				}
65				return TrailReport{Prose: prose}, true
66			}
67			return TrailReport{Comments: comments}, len(comments) > 0
68		}
69		var merged []TrailComment
70		var unstructured []reviewtypes.AgentRun
71		for _, run := range usableAgentRuns(summary) {
72			prose, comments, ok := splitTrailJSON(reportText(run.Buffer))
73			if !contractCoversProse(prose, comments, ok) {
74				unstructured = append(unstructured, run)
75				continue
76			}
77			merged = append(merged, comments...)
78		}
79		report := TrailReport{Comments: merged, Prose: combinedReviewNarratives(unstructured)}
80		return report, len(merged) > 0 || len(unstructured) > 0
81	}
82	
83	// contractCoversProse reports whether a valid contract can be posted in place
84	// of its prose: the prose reports no finding the comments leave out. The
85	// prose normally repeats every comment, so it is posted instead of, not
86	// alongside, an incomplete contract.
87	func contractCoversProse(prose string, comments []TrailComment, ok bool) bool {
88		if !ok {
89			return false
90		}
91		if len(comments) == 0 {
92			return !proseReportsFindings(prose)
93		}
94		return markedFindingCount(prose) <= len(comments)
95	}
96	
97	// markedFindingCount counts the findings prose reports with a severity, the
98	// finding shape the output format asks for: lines at any indentation, list
99	// items included, that open with a severity marker, and findings without one
100	// under a severity heading.
101	func markedFindingCount(prose string) int {
102		count := 0
103		for _, line := range strings.Split(prose, "\n") {
104			if _, ok := severityLabel(line); ok {
105				continue
106			}
107			trimmed := strings.TrimSpace(line)
108			if item, ok := ListItemText(trimmed); ok {
109				trimmed = item
110			}
111			if StartsWithSeverityMarker(trimmed) {
112				count++
113			}
114		}
115		for _, finding := range SplitProseFindings(prose) {
116			if finding.Severity != "" && !StartsWithSeverityMarker(finding.Text) {
117				count++
118			}
119		}
120		return count
121	}
122	
123	// reportText returns a reviewer's report: the last stretch of text between
124	// tool calls that ends with a valid contract line, or "" if none does. It is
125	// found by the contract line rather than by position, so a tool call after
126	// the report does not hide it, and earlier exploration narration, whose
127	// bullets ("I'll check:\n- retry.go") are not findings, is left out. A tool
128	// call inside a message, where the next text continues it as a delta, is not
129	// a boundary. A stretch holding only the contract line also takes the last
130	// text before it when that text reports findings by more than bullets, so a
131	// report written before the final tool calls is still checked against the
132	// line while a bulleted file list is not.
133	func reportText(buf []reviewtypes.Event) string {
134		end := len(buf)
135		for i := len(buf) - 1; i >= -1; i-- {
136			if i >= 0 && !isTextBoundary(buf, i) {
137				continue
138			}
139			text := joinAssistantText(buf[i+1 : end])
140			prose, payload, found := splitTrailJSONPayload(text)
141			if _, ok := decodeTrailComments(payload["comments"]); !found || !ok {
142				end = i
143				continue
144			}
145			if prose == "" && i >= 0 {
146				if before := lastTextBefore(buf, i); proseReportsMarkedFindings(before) {
147					return before + "\n\n" + text
148				}
149			}
150			return text
151		}
152		return ""
153	}
154	
155	// lastTextBefore returns the last non-empty stretch of text before buf[end].
156	func lastTextBefore(buf []reviewtypes.Event, end int) string {
157		for i := end - 1; i >= -1; i-- {
158			if i >= 0 && !isTextBoundary(buf, i) {
159				continue
160			}
161			if text := joinAssistantText(buf[i+1 : end]); text != "" {
162				return text
163			}
164			end = i
165		}
166		return ""
167	}
168	
169	// isTextBoundary reports whether buf[i] is a tool call that separates two
170	// stretches of text rather than interrupting a message.
171	func isTextBoundary(buf []reviewtypes.Event, i int) bool {
172		_, ok := buf[i].(reviewtypes.ToolCall)
173		return ok && !continuesMessage(buf[i+1:])
174	}
175	
176	// continuesMessage reports whether the first text in buf continues the
177	// message before it.
178	func continuesMessage(buf []reviewtypes.Event) bool {
179		for _, ev := range buf {
180			if at, ok := ev.(reviewtypes.AssistantText); ok {
181				return at.Delta
182			}
183		}
184		return false
185	}
186	
187	// splitTrailJSON separates a trailing contract-shaped JSON object (one line,
188	// a fenced block, or a pretty-printed block, with a "summary" or "comments"
189	// key) from the prose before it, so a malformed contract is never posted as
190	// finding text. Other trailing JSON, such as a config snippet quoted as
191	// evidence, stays in the prose. A JSON-only reply contributes its summary as
192	// the prose instead. ok reports a valid contract: a "comments" array.
193	// Entries without a body are dropped.
194	func splitTrailJSON(text string) (prose string, comments []TrailComment, ok bool) {
195		prose, payload, found := splitTrailJSONPayload(text)
196		if !found {
197			return prose, nil, false
198		}
199		if prose == "" {
200			var summary string
201			if json.Unmarshal(payload["summary"], &summary) == nil {
202				prose = strings.TrimSpace(summary)
203			}
204		}
205		comments, ok = decodeTrailComments(payload["comments"])
206		return prose, comments, ok
207	}
208	
209	// splitTrailJSONPayload finds a trailing contract-shaped JSON object and
210	// returns the prose before it and its decoded keys. found is false, with
211	// the whole text as prose, when there is none.
212	func splitTrailJSONPayload(text string) (prose string, payload map[string]json.RawMessage, found bool) {
213		text = strings.TrimSpace(text)
214		lines := strings.Split(text, "\n")
215		end := len(lines)
216		fenced := end > 1 && strings.TrimSpace(lines[end-1]) == "```"
217		if fenced {
218			end--
219		}
220		for start := end - 1; start >= 0 && start >= end-maxTrailJSONLines; start-- {
221			if !strings.HasPrefix(strings.TrimSpace(lines[start]), "{") {
222				continue
223			}
224			payload = nil
225			if err := json.Unmarshal([]byte(strings.Join(lines[start:end], "\n")), &payload); err != nil {
226				continue
227			}
228			_, hasSummary := payload["summary"]
229			_, hasComments := payload["comments"]
230			if !hasSummary && !hasComments {
231				break
232			}
233			proseEnd := start
234			if fenced && proseEnd > 0 && strings.HasPrefix(strings.TrimSpace(lines[proseEnd-1]), "```") {
235				proseEnd--
236			}
237			return strings.TrimSpace(strings.Join(lines[:proseEnd], "\n")), payload, true
238		}
239		return text, nil, false
240	}
241	
242	func decodeTrailComments(raw json.RawMessage) ([]TrailComment, bool) {
243		if !strings.HasPrefix(strings.TrimSpace(string(raw)), "[") {
244			return nil, false
245		}
246		var decoded []TrailComment
247		if err := json.Unmarshal(raw, &decoded); err != nil {
248			return nil, false
249		}
250		comments := []TrailComment{}
251		for _, comment := range decoded {
252			if strings.TrimSpace(comment.Body) != "" {
253				comments = append(comments, comment)
254			}
255		}
256		return comments, true
257	}
258	
259	// stripTrailJSON removes a valid trailing contract line for display. Only a
260	// run that asked for the line has one; elsewhere a trailing JSON block is the
261	// reviewer's own text and stays.
262	func stripTrailJSON(text string, trailFindingsJSON bool) string {
263		if !trailFindingsJSON {
264			return text
265		}
266		if prose, _, ok := splitTrailJSON(text); ok {
267			return prose
268		}
269		return text
270	}
271	
272	// proseReportsFindings reports whether prose contradicts an empty comments
273	// array: a list item at any indentation, or a finding proseReportsMarkedFindings
274	// recognizes. These are the shapes the output format asks for, so a clean
275	// review has none of them. A list item that only says a section is empty
276	// ("- None") is not a finding.
277	func proseReportsFindings(prose string) bool {
278		for _, line := range strings.Split(prose, "\n") {
279			if item, ok := ListItemText(strings.TrimSpace(line)); ok && !isNoFindingsText(item) {
280				return true
281			}
282		}
283		return proseReportsMarkedFindings(prose)
284	}
285	
286	// proseReportsMarkedFindings reports whether prose reports findings by more
287	// than bullets: a severity marker or feedback label such as "Nits:" at any
288	// indentation, a finding under a severity heading, or a verdict, labeled or
289	// not, that itself says there is feedback. A bulleted file list in
290	// exploration narration has none of these.
291	func proseReportsMarkedFindings(prose string) bool {
292		for _, line := range strings.Split(prose, "\n") {
293			if _, ok := severityLabel(line); ok {
294				continue
295			}
296			trimmed := strings.TrimSpace(line)
297			if item, ok := ListItemText(trimmed); ok {
298				trimmed = item
299			}
300			lower := strings.ToLower(trimMarkdownEmphasis(trimmed))
301			if after, found := strings.CutPrefix(lower, "verdict"); found {
302				lower = trimMarkdownEmphasis(strings.TrimLeft(after, ":-—– "))
303			}
304			if StartsWithSeverityMarker(lower) {
305				return true
306			}
307			for _, prefix := range []string{
308				"request changes", "request_changes", "changes requested", "approve with nits",
309				"needs changes", "needs work", "changes needed",
310				"nits:", "issues:", "concerns:", "suggestions:", "findings:", "problems:", "blocking:",
311			} {
312				if strings.HasPrefix(lower, prefix) {
313					return true
314				}
315			}
316		}
317		return markedFindingCount(prose) > 0
318	}
319	
320	func trimMarkdownEmphasis(s string) string {
321		return strings.TrimLeft(s, "#>*_` ")
322	}
323	
324	// StartsWithSeverityMarker reports whether line, after leading Markdown
325	// emphasis, opens with a severity tag: bracketed ("[high]"), delimited
326	// ("high —", "p2:"), closed by emphasis ("**High** ..."), or alone (a "### High"
327	// heading). A word that merely starts with a marker ("Highlights") is not one.
328	func StartsWithSeverityMarker(line string) bool {
329		return LeadingSeverity(line) != ""
330	}
331	
332	// LeadingSeverity returns the severity tag line opens with, in lower case, as
333	// StartsWithSeverityMarker recognizes it, or "" if there is none.
334	func LeadingSeverity(line string) string {
335		lower := strings.ToLower(trimMarkdownEmphasis(strings.TrimSpace(line)))
336		for _, marker := range severityMarkers {
337			if strings.HasPrefix(lower, "["+marker+"]") {
338				return marker
339			}
340			rest, found := strings.CutPrefix(lower, marker)
341			if !found {
342				continue
343			}
344			if strings.TrimSpace(rest) == "" {
345				return marker
346			}
347			for _, suffix := range []string{" —", " –", " -", ":", "*", "_"} {
348				if strings.HasPrefix(rest, suffix) {
349					return marker
350				}
351			}
352		}
353		return ""
354	}
355	
356	var severityMarkers = []string{"critical", "high", "medium", "low", "p0", "p1", "p2", "p3", "nit"}
357	
358	// severityLabel reports whether line, unindented, holds only a severity
359	// label ("### High", "**Low:**", "Nits:") and returns it in lower case.
360	func severityLabel(line string) (string, bool) {
361		if line != strings.TrimLeft(line, " \t") {
362			return "", false
363		}
364		label := strings.TrimLeft(strings.TrimSpace(line), "#>*_`[ ")
365		label = strings.ToLower(strings.TrimRight(label, ":*_`] "))
366		for _, marker := range severityMarkers {
367			if label == marker || label == marker+"s" {
368				return label, true
369			}
370		}
371		return "", false
372	}
373	
374	var noFindingsPattern = regexp.MustCompile(`^(none|nothing|n/?a|no (\S+ ){0,3}(issues|findings|concerns|problems))( (found|identified|noted|to report))?$`)
375	
376	// isNoFindingsText reports whether text only says a section is empty
377	// ("None.", "No high-severity issues."), as reviews often write under a
378	// severity heading with nothing in it.
379	func isNoFindingsText(text string) bool {
380		return noFindingsPattern.MatchString(strings.ToLower(strings.Trim(text, "*_`.!:() \t")))
381	}
382	
383	// ProseFinding is one top-level finding in prose. Severity is the label of
384	// the severity heading it sits under ("high", "p2"), or "" outside one.
385	type ProseFinding struct {
386		Text     string
387		Severity string
388	}
389	
390	// SplitProseFindings splits prose into its top-level findings: list items and
391	// lines that open with a severity marker, each with the lines that continue
392	// it. A line holding only a severity ("### High", "**Low:**") groups the
393	// findings below it, up to the next heading, rather than being one; text
394	// under it that is not a list item is a finding, and a placeholder such as
395	// "None." is not. Trail posting
396	// counts findings with this and the bridge posts them, so both agree on what
397	// a finding is.
398	func SplitProseFindings(prose string) []ProseFinding {
399		var findings []ProseFinding
400		var current strings.Builder
401		group := ""
402		flush := func() {
403			text := strings.TrimSpace(current.String())
404			current.Reset()
405			if text != "" {
406				findings = append(findings, ProseFinding{Text: text, Severity: group})
407			}
408		}
409		for _, line := range strings.Split(strings.TrimSpace(prose), "\n") {
410			if label, ok := severityLabel(line); ok {
411				flush()
412				group = label
413				continue
414			}
415			if group != "" && strings.HasPrefix(line, "#") {
416				flush()
417				group = ""
418				continue
419			}
420			if item, ok := topLevelListItemText(line); ok {
421				flush()
422				if !isNoFindingsText(item) {
423					current.WriteString(item)
424				}
425				continue
426			}
427			if line == strings.TrimLeft(line, " \t") && StartsWithSeverityMarker(line) {
428				flush()
429				current.WriteString(strings.TrimSpace(line))
430				continue
431			}
432			if current.Len() == 0 {
433				if group == "" || strings.TrimSpace(line) == "" || isNoFindingsText(line) {
434					continue
435				}
436			} else {
437				current.WriteByte('\n')
438			}
439			current.WriteString(line)
440		}
441		flush()
442		return findings
443	}
444	
445	func topLevelListItemText(line string) (string, bool) {
446		if line != strings.TrimLeft(line, " \t") {
447			return "", false
448		}
449		item, ok := ListItemText(strings.TrimSpace(line))
450		return item, ok && item != ""
451	}
452	
453	// ListItemText returns the text of a Markdown list item ("- ", "* ", "+ ",
454	// "• ", "1. ", "1) ") and whether trimmed, a line without surrounding space,
455	// is one.
456	func ListItemText(trimmed string) (string, bool) {
457		for _, bullet := range []string{"- ", "* ", "+ ", "• "} {
458			if item, found := strings.CutPrefix(trimmed, bullet); found {
459				return strings.TrimSpace(item), true
460			}
461		}
462		digits := len(trimmed) - len(strings.TrimLeft(trimmed, "0123456789"))
463		if digits == 0 {
464			return "", false
465		}
466		for _, delim := range []string{". ", ") "} {
467			if item, found := strings.CutPrefix(trimmed[digits:], delim); found {
468				return strings.TrimSpace(item), true
469			}
470		}
471		return "", false
472	}
