package review

import (
	"testing"

	rt "github.com/entireio/cli/cmd/entire/cli/review/types"
)

func show8(t *testing.T, name, agg string) {
	defer func() {
		if r := recover(); r != nil {
			t.Logf("== %s: PANIC %v", name, r)
		}
	}()
	r, post := trailReportFor(rt.RunSummary{}, agg)
	t.Logf("== %s: post=%v comments=%d prose?=%v", name, post, len(r.Comments), r.Prose != "")
}

const w1 = "\n{\"summary\":\"one issue\",\"comments\":[{\"severity\":\"high\",\"body\":\"Unbounded retry loop never stops on 503; cap attempts.\",\"location\":{\"granularity\":\"line\",\"file_path\":\"retry.go\",\"start_line\":42}}]}"
const w0 = "\n{\"summary\":\"Looks good.\",\"comments\":[]}"

func TestZZProbe8(t *testing.T) {
	show8(t, "D1 em-dash empty section", "### High\n—\n\n### Medium\n—\n\n### Low\n—\n\n**Verdict:** Approve"+w0)
	show8(t, "D2 en-dash empty section", "### High\n–\n\n### Low\n–"+w0)
	hi := "### High\n- `retry.go:42`: the retry loop never stops on 503.\n\n### Medium\n"
	show8(t, "G1 'No test ... regressions' paragraph, contract 1", hi+"No test covers the 503 path in the auth client, so regressions there would go unnoticed.\n\n### Low\nNone."+w1)
	show8(t, "G2 'No ... risks' bullet, contract 1", hi+"- No cap on the token refresh loop, which risks hammering the auth server.\n\n### Low\nNone."+w1)
	show8(t, "G3 'No test ... bug' only finding, empty contract", "### Medium\n- No test covers the 503 path, so this bug class could come back unnoticed.\n\n### Low\nNone."+w0)
	show8(t, "G4 'No timeout ... risk' only finding, empty contract", "### High\nNo timeout on the HTTP client in the auth flow, a real availability risk under load.\n\n### Low\nNone."+w0)
}
EOF
printf '{"Replace":{"%s/cmd/entire/cli/review/zz_probe_test.go":"%s/probe8_test.go"}}' $R $S > $S/ov8.json
